/* frost-field - shadcn/ui theme (Tailwind v4).
   Drop into your global CSS after `@import "tailwindcss";`.
   Values are the identity spec from identity.json. */

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-ok: var(--ok);
  --color-ok-soft: var(--ok-soft);
  --color-ok-foreground: var(--ok-foreground);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-warn-foreground: var(--warn-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-viz-violet: var(--viz-violet);
  --color-viz-sky: var(--viz-sky);
  --color-viz-mint: var(--viz-mint);
  --color-viz-rose: var(--viz-rose);
  --font-display: "Manrope", "Inter", system-ui, sans-serif;
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: ui-monospace, Menlo, Consolas, monospace;
  /* Radius ladder: 14px controls, 20px cards, pills for chips/badges/docks. */
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: var(--radius);
  --radius-lg: calc(var(--radius) + 2px);
  --radius-xl: calc(var(--radius) + 6px);
}

:root,
[data-theme="frost-field"] {
  --background: #f7f7fb; /* ground under the field */
  --foreground: #1c1c28; /* ink */
  --card: rgba(255, 255, 255, 0.72); /* strong fill - cards carry body text */
  --card-foreground: #1c1c28;
  --popover: rgba(255, 255, 255, 0.72); /* strong fill - popovers read over content */
  --popover-foreground: #1c1c28;
  --primary: #6a5ae0; /* action violet, 5.1:1 on white */
  --primary-foreground: #ffffff; /* 5.1:1 on the action violet */
  --secondary: #eceef8; /* lavender wash */
  --secondary-foreground: #33334a; /* 10.6:1 on the wash */
  --muted: #ededf3; /* quiet fills and skeletons */
  --muted-foreground: #5c5c6e; /* 6.5:1 on white */
  --accent: #eceef8; /* interactive wash sits in the lavender family */
  --accent-foreground: #33334a;
  --destructive: #c93a56; /* rose, 5:1 with white */
  --destructive-foreground: #ffffff;
  --ok: #2f9d6f; /* mint-family status, UI/large text */
  --ok-soft: #e2f6ec;
  --ok-foreground: #1f7a54; /* 4.7:1 on the soft wash */
  --warn: #b97f24;
  --warn-soft: #fbf0dd;
  --warn-foreground: #7c540f; /* 6:1 on the soft wash */
  --border: #b9b9cd; /* hairline for inputs on solid ground */
  --input: #b9b9cd;
  --ring: #6a5ae0;
  --radius: 0.875rem; /* 14px controls; the ladder derives cards */
  --font-display: "Manrope", "Inter", system-ui, sans-serif;
  --font-sans: "Inter", system-ui, sans-serif;
  --font-mono: ui-monospace, Menlo, Consolas, monospace;

  /* The field: fixed pastel aurora behind every surface. */
  --field: linear-gradient(135deg, #e6e0f8 0%, #dcebf7 32%, #dff2e9 64%, #fde8dd 100%);

  /* Glass recipe (regular glass discipline): fills, blur, boundary, shadow. */
  --glass-fill: rgba(255, 255, 255, 0.55); /* regular panels */
  --glass-fill-strong: rgba(255, 255, 255, 0.72); /* mandatory under body text */
  --glass-fill-chrome: rgba(255, 255, 255, 0.35); /* hero panels and docks only */
  --glass-blur: blur(20px) saturate(150%);
  --glass-border: rgba(255, 255, 255, 0.6); /* 1px light boundary */
  --glass-rim: inset 0 1px 0 rgba(255, 255, 255, 0.7); /* top rim highlight */
  --glass-shadow: 0 8px 32px rgba(31, 38, 135, 0.1);

  /* Solid-surface fallback: reduced-transparency panels, geometry holds. */
  --solid-surface: #fbfbfd;

  /* Data-viz family: 400-weight pastels, thin strokes, never fills. */
  --viz-violet: #a78bfa;
  --viz-sky: #7cc7f2;
  --viz-mint: #74d0ae;
  --viz-rose: #f2a6bc;
  color-scheme: light;
}

/* Accessibility floor: reduced transparency gets genuinely solid panels.
   Geometry holds - every token swaps its value, nothing re-flows. */
@media (prefers-reduced-transparency: reduce) {
  :root,
  [data-theme="frost-field"] {
    --card: var(--solid-surface);
    --popover: var(--solid-surface);
    --glass-fill: var(--solid-surface);
    --glass-fill-strong: var(--solid-surface);
    --glass-fill-chrome: var(--solid-surface);
    --glass-blur: none;
    --glass-border: #e4e4ee;
    --glass-shadow: 0 1px 3px rgba(31, 38, 135, 0.08);
  }
}

/* Accessibility floor: no backdrop-filter support -> near-opaque fills so
   text contrast never depends on the blur that will not happen. */
@supports not (backdrop-filter: blur(1px)) {
  :root,
  [data-theme="frost-field"] {
    --glass-fill: rgba(255, 255, 255, 0.95);
    --glass-fill-strong: rgba(255, 255, 255, 0.95);
    --glass-fill-chrome: rgba(255, 255, 255, 0.95);
  }
}

/* Identity signatures: the fixed aurora field on the body, Manrope display
   headings, tabular numerals, and the optional drift (flavor, never load
   bearing). */
body {
  font-family: var(--font-sans);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  background-color: var(--background);
  background-image: var(--field);
  background-attachment: fixed;
}
h1, h2, h3, .font-display {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: -0.01em;
  color: var(--foreground);
}
h1 { letter-spacing: -0.02em; }
.tabular { font-variant-numeric: tabular-nums; }

/* Optional field drift: a slow hue sway behind fixed panels. Flavor only;
   prefers-reduced-motion (below) stills it. */
@keyframes field-drift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
.field-drift {
  background-size: 160% 160%;
  animation: field-drift 90s ease-in-out infinite;
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
}


/* ---- overrides ---- */
/* frost-field overrides - the opinionated treatment on top of stock shadcn.
   Layer AFTER shadcn styles. Each rule is a deliberate identity decision:
   surfaces are glass over the fixed field, the 0.72 strong fill sits under
   every body-text surface, and the identity glows only via the field. */

/* The glass recipe lives in three classes so block-level panels (hero,
   dock, chips) reuse exactly what the components wear. backdrop-filter
   always ships with its -webkit- prefix. */
[data-identity="frost-field"] .glass,
[data-identity="frost-field"] .glass-strong,
[data-identity="frost-field"] .glass-chrome {
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  border: 1px solid var(--glass-border);
  box-shadow: var(--glass-rim), var(--glass-shadow);
}
[data-identity="frost-field"] .glass { background: var(--glass-fill); }
[data-identity="frost-field"] .glass-strong { background: var(--glass-fill-strong); }
[data-identity="frost-field"] .glass-chrome { background: var(--glass-fill-chrome); }

/* Cards are glass-strong: they carry body text, so the 0.72 fill is the
   law. 20px radius, rim highlight, soft shadow, gentle hover lift. */
[data-identity="frost-field"] [data-slot="card"] {
  border: 1px solid var(--glass-border);
  border-radius: 20px;
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  box-shadow: var(--glass-rim), var(--glass-shadow);
  transition: transform 200ms cubic-bezier(0.22, 0.61, 0.36, 1),
    box-shadow 200ms cubic-bezier(0.22, 0.61, 0.36, 1);
}
[data-identity="frost-field"] a[data-slot="card"]:hover,
[data-identity="frost-field"] .hover-lift:hover [data-slot="card"] {
  transform: translateY(-2px);
  box-shadow: var(--glass-rim), 0 12px 40px rgba(31, 38, 135, 0.14);
}

/* Overlays float like the hero: popover, dialog, and sheet chrome wear the
   strong fill (they read over content), 20px radius, rim + shadow. */
[data-identity="frost-field"] [data-slot="popover-content"],
[data-identity="frost-field"] [data-slot="dialog-content"],
[data-identity="frost-field"] [data-slot="sheet-content"] {
  border: 1px solid var(--glass-border);
  border-radius: 20px;
  backdrop-filter: var(--glass-blur);
  -webkit-backdrop-filter: var(--glass-blur);
  box-shadow: var(--glass-rim), var(--glass-shadow);
}

/* Buttons are pills: the wellness genre's control shape. Primary carries a
   soft violet shadow; hover lifts 1px; nothing bounces. */
[data-identity="frost-field"] [data-slot="button"] {
  border-radius: 999px;
  font-weight: 600;
  transition: transform 180ms cubic-bezier(0.22, 0.61, 0.36, 1),
    box-shadow 180ms cubic-bezier(0.22, 0.61, 0.36, 1);
}
[data-identity="frost-field"] [data-slot="button"].bg-primary {
  box-shadow: 0 4px 14px rgba(106, 90, 224, 0.35);
}
[data-identity="frost-field"] [data-slot="button"]:hover:not(:disabled) {
  transform: translateY(-1px);
}
[data-identity="frost-field"] [data-slot="button"]:active {
  transform: translateY(0);
}
[data-identity="frost-field"] [data-slot="button"]:disabled {
  opacity: 0.55;
}

/* Badges and status chips are pills; soft status fills stay legible. */
[data-identity="frost-field"] [data-slot="badge"] {
  border-radius: 999px;
  font-weight: 600;
}

/* Inputs sit on glass: translucent white fill, cool hairline, 14px radius.
   Focus is the violet halo, never a border-color flip. */
[data-identity="frost-field"] input,
[data-identity="frost-field"] textarea,
[data-identity="frost-field"] select {
  border-radius: var(--radius);
  background: rgba(255, 255, 255, 0.6);
  transition: box-shadow 160ms ease;
}

/* Focus: soft two-step halo (wash, then action violet). Never a hard
   1px outline flip; radius untouched so pills keep their shape. */
[data-identity="frost-field"] :focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px var(--secondary), 0 0 0 5px rgba(106, 90, 224, 0.55);
}

/* Accessibility floor: forced colors flatten the glass to plain bordered
   surfaces. The system palette takes over; geometry holds. */
@media (forced-colors: active) {
  [data-identity="frost-field"] [data-slot="card"],
  [data-identity="frost-field"] [data-slot="popover-content"],
  [data-identity="frost-field"] [data-slot="dialog-content"],
  [data-identity="frost-field"] [data-slot="sheet-content"],
  [data-identity="frost-field"] .glass,
  [data-identity="frost-field"] .glass-strong,
  [data-identity="frost-field"] .glass-chrome {
    border: 1px solid CanvasText;
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
    box-shadow: none;
  }
  [data-identity="frost-field"] [data-slot="button"].bg-primary {
    box-shadow: none;
  }
}

/* Thumb floor: controls hold a 44px hit target on touch. Covers the
   floating bar's inline nav (sm+) and the pill dock (below sm). Mobile
   WebKit detaches fixed body backgrounds, so the field scrolls with the
   page under a coarse pointer. */
@media (pointer: coarse) {
  body {
    background-attachment: scroll;
  }
  [data-identity="frost-field"] [data-slot="button"] {
    min-height: 44px;
  }
  [data-identity="frost-field"] header nav a {
    display: inline-flex;
    align-items: center;
    min-height: 44px;
  }
}

import type { ReactNode } from "react"
import { RotateCw } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Card, CardContent } from "@/components/ui/card"

/* Long-form reading on glass: the article column sits on a strong-fill
   glass plate (body text law), with the full data grammar so a CMS-driven
   article never ships blank. */
export function Article({
  eyebrow,
  title,
  meta,
  status = "ready",
  onRetry,
  children,
}: {
  eyebrow: string
  title: string
  meta: string
  status?: "ready" | "loading" | "error" | "empty"
  onRetry?: () => void
  children: ReactNode
}) {
  return (
    <article className="mx-auto max-w-[760px] px-6 py-14">
      <span className="text-[11.5px] font-bold uppercase tracking-[0.16em] text-primary">{eyebrow}</span>
      <h1 className="mt-3 font-display text-[clamp(28px,3.4vw,36px)] font-bold leading-[1.12] tracking-[-0.02em]">
        {title}
      </h1>
      <p className="mt-3 text-[13px] text-muted-foreground">{meta}</p>
      <div className="glass-strong mt-8 rounded-[20px] px-7 py-8 sm:px-10">
        {status === "loading" && (
          <div aria-label="Loading article" className="space-y-3">
            {Array.from({ length: 6 }).map((_, i) => (
              <div
                key={i}
                className={`h-3.5 animate-pulse rounded-full bg-muted motion-reduce:animate-none ${
                  i % 3 === 2 ? "w-2/3" : "w-full"
                }`}
              />
            ))}
          </div>
        )}
        {status === "error" && (
          <div className="py-8 text-center">
            <h2 className="font-display text-[16px] font-bold">This story didn&rsquo;t load</h2>
            <p className="mt-2 text-[13px] leading-relaxed text-muted-foreground">
              The piece is saved on the server. Nothing was lost.
            </p>
            <Button size="sm" variant="outline" className="mt-4" onClick={onRetry}>
              <RotateCw className="mr-1.5 size-3.5" /> Try again
            </Button>
          </div>
        )}
        {status === "empty" && (
          <div className="py-8 text-center">
            <h2 className="font-display text-[16px] font-bold">Nothing published yet</h2>
            <p className="mt-2 text-[13px] leading-relaxed text-muted-foreground">
              New practice notes land here every week.
            </p>
          </div>
        )}
        {status === "ready" && (
          <div className="flex flex-col gap-6 text-[15.5px] leading-[1.65] [&_blockquote]:border-l-4 [&_blockquote]:border-viz-violet/60 [&_blockquote]:pl-4 [&_blockquote]:italic [&_h2]:mt-8 [&_h2]:font-display [&_h2]:text-[20px] [&_h2]:font-bold [&_h2]:tracking-[-0.01em] [&_li]:mt-2 [&_ul]:ml-5 [&_ul]:list-disc">
            {children}
          </div>
        )}
      </div>
    </article>
  )
}

export function Callout({ tone = "info", children }: { tone?: "info" | "warn"; children: ReactNode }) {
  return (
    <Card className={`py-0 ${tone === "warn" ? "bg-warn-soft" : "bg-secondary"}`}>
      <CardContent className={`p-5 text-[13.5px] leading-relaxed ${tone === "warn" ? "text-warn-foreground" : "text-secondary-foreground"}`}>
        {children}
      </CardContent>
    </Card>
  )
}

export function Kpi({ value, label }: { value: string; label: string }) {
  return (
    <Card className="py-5">
      <CardContent className="px-5">
        <b className="font-display text-[28px] font-bold leading-none tracking-[-0.02em] tabular-nums">{value}</b>
        <span className="mt-2 block text-[11.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
          {label}
        </span>
      </CardContent>
    </Card>
  )
}

import { Loader2 } from "lucide-react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"

/* The sign-in card: strong-fill glass (it is all body text), centered over
   the field. The full form grammar - idle, submitting, error - is part of
   the block, wired for assistive tech. */
export function AuthCard({
  title = "Welcome back",
  description = "Sign in to continue your practice.",
  primaryCta = "Sign in",
  status = "idle",
}: {
  title?: string
  description?: string
  primaryCta?: string
  status?: "idle" | "submitting" | "error"
} = {}) {
  return (
    <div className="glass-strong mx-auto w-full max-w-sm rounded-[20px] p-6 sm:p-8">
      <h1 className="font-display text-[20px] font-bold tracking-[-0.01em]">{title}</h1>
      <p className="mt-1.5 text-[13px] leading-relaxed text-muted-foreground">{description}</p>
      <form className="mt-6 flex flex-col gap-4">
        <div className="grid gap-2">
          <Label htmlFor="email">Email</Label>
          <Input id="email" type="email" placeholder="you@example.com" autoCapitalize="none" aria-invalid={status === "error"} />
        </div>
        <div className="grid gap-2">
          <Label htmlFor="password">Password</Label>
          <Input id="password" type="password" aria-invalid={status === "error"} aria-describedby={status === "error" ? "auth-error" : undefined} />
        </div>
        {status === "error" && (
          <p id="auth-error" role="alert" className="text-[13px] font-medium text-destructive">
            That email and password don&rsquo;t match. Try again.
          </p>
        )}
        <Button type="submit" className="mt-2 h-11" disabled={status === "submitting"}>
          {status === "submitting" ? (
            <>
              <Loader2 className="mr-2 size-4 animate-spin motion-reduce:animate-none" aria-hidden />
              Signing you in&hellip;
            </>
          ) : (
            primaryCta
          )}
        </Button>
      </form>
    </div>
  )
}

import type { ReactNode } from "react"
import { Flame, RotateCw } from "lucide-react"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"

/* The wellness dashboard: floating glass chrome over the field, KPI tiles
   with large numerals, a mood check-in, a streak grid, and program cards.
   One idea per card, 20px+ padding, no dense data anywhere. */

export function DashboardShell({
  title,
  nav,
  actions,
  stats,
  status = "ready",
  onRetry,
  children,
}: {
  title: string
  nav: { label: string; active?: boolean }[]
  actions?: ReactNode
  stats: { value: string; label: string }[]
  status?: "ready" | "loading" | "error"
  onRetry?: () => void
  children: ReactNode
}) {
  return (
    <div className="min-h-screen">
      <header className="sticky top-4 z-40 mx-auto max-w-[1120px] px-4 sm:px-6">
        <div className="glass-strong flex min-h-[60px] flex-wrap items-center gap-x-4 gap-y-1 rounded-[20px] px-5 py-2 sm:h-[60px] sm:flex-nowrap sm:py-0">
          <span className="min-w-0 truncate font-display text-[19px] font-bold tracking-[-0.01em]">
            {title}
          </span>
          <nav className="ml-auto hidden shrink-0 items-center gap-4 sm:flex sm:gap-6">
            {nav.map((n) => (
              <a
                key={n.label}
                href="#"
                className={`py-2 text-sm transition-colors ${
                  n.active ? "font-semibold text-foreground" : "font-medium text-muted-foreground hover:text-primary"
                }`}
              >
                {n.label}
              </a>
            ))}
          </nav>
          {actions && <div className="ml-auto hidden shrink-0 items-center gap-3 sm:flex">{actions}</div>}
        </div>
        <nav aria-label="Sections" className="glass-strong mt-2 flex items-center gap-1 overflow-x-auto rounded-[20px] p-1.5 sm:hidden">
          {nav.map((n) => (
            <a
              key={n.label}
              href="#"
              className={`shrink-0 rounded-full px-4 py-2 text-sm transition-colors ${
                n.active ? "bg-primary font-semibold text-primary-foreground" : "text-muted-foreground"
              }`}
            >
              {n.label}
            </a>
          ))}
        </nav>
      </header>

      <main className="mx-auto max-w-[1120px] px-6 py-10">
        <div className="mb-6 grid grid-cols-2 gap-4 lg:grid-cols-4">
          {status === "loading" &&
            Array.from({ length: 4 }).map((_, i) => (
              <Card key={i} className="py-5">
                <CardContent className="px-5" aria-label="Loading today's stats">
                  <div className="h-8 w-16 animate-pulse rounded-lg bg-muted motion-reduce:animate-none" />
                  <div className="mt-2 h-3 w-20 animate-pulse rounded bg-muted motion-reduce:animate-none" />
                </CardContent>
              </Card>
            ))}
          {status === "error" && (
            <Card className="col-span-2 py-8 lg:col-span-4">
              <CardContent className="px-6 text-center">
                <h3 className="font-display text-[16px] font-bold">Today&rsquo;s stats didn&rsquo;t load</h3>
                <p className="mt-2 text-[13px] leading-relaxed text-muted-foreground">
                  Your history is safe. Nothing was lost.
                </p>
                <Button size="sm" variant="outline" className="mt-4" onClick={onRetry}>
                  <RotateCw className="mr-1.5 size-3.5" /> Try again
                </Button>
              </CardContent>
            </Card>
          )}
          {status === "ready" &&
            stats.map((s) => (
              <Card key={s.label} className="py-5">
                <CardContent className="px-5">
                  <b className="font-display text-[32px] font-bold leading-none tracking-[-0.02em] tabular-nums">
                    {s.value}
                  </b>
                  <span className="mt-2 block text-[11.5px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
                    {s.label}
                  </span>
                </CardContent>
              </Card>
            ))}
        </div>
        {children}
      </main>
    </div>
  )
}

/* Status pill for sessions and check-ins; soft fills only, pills only. */
export function StatBadge({ label, tone = "muted" }: { label: string; tone?: "muted" | "ok" | "warn" | "danger" }) {
  const tones = {
    muted: "bg-secondary text-secondary-foreground",
    ok: "bg-ok-soft text-ok-foreground",
    warn: "bg-warn-soft text-warn-foreground",
    danger: "bg-destructive/10 text-destructive",
  }
  return <Badge className={`px-2.5 py-0.5 text-[11px] ${tones[tone]}`}>{label}</Badge>
}

const moods = [
  { value: 1, label: "Rough", face: "•︵•" },
  { value: 2, label: "Low", face: "•_•" },
  { value: 3, label: "Okay", face: "•‿•" },
  { value: 4, label: "Good", face: "ᵔ‿ᵔ" },
  { value: 5, label: "Great", face: "ᵔᴥᵔ" },
]

/* The daily mood check-in: five faces, one tap. The selected face gets the
   action violet; everything else stays glass. */
export function MoodCheckin({
  value = 4,
  onSelect,
  status = "ready",
  onRetry,
}: {
  value?: number
  onSelect?: (value: number) => void
  status?: "ready" | "loading" | "error"
  onRetry?: () => void
} = {}) {
  return (
    <Card>
      <CardHeader className="px-6 pt-6">
        <CardTitle className="font-display text-[17px] font-bold tracking-[-0.01em]">How are you feeling?</CardTitle>
        <CardDescription className="text-[13px]">One tap. You can change it later.</CardDescription>
      </CardHeader>
      <CardContent className="px-6 pb-6">
        {status === "loading" && (
          <div className="flex gap-2" aria-label="Loading today's check-in">
            {moods.map((m) => (
              <div key={m.value} className="h-10 flex-1 animate-pulse rounded-full bg-muted motion-reduce:animate-none" />
            ))}
          </div>
        )}
        {status === "error" && (
          <div className="text-center">
            <p className="text-[13px] text-muted-foreground">Couldn&rsquo;t reach today&rsquo;s check-in. Nothing was lost.</p>
            <Button size="sm" variant="outline" className="mt-3" onClick={onRetry}>
              <RotateCw className="mr-1.5 size-3.5" /> Try again
            </Button>
          </div>
        )}
        {status === "ready" && (
          <div className="flex flex-wrap gap-2" role="group" aria-label="Mood check-in">
            {moods.map((m) => (
              <button
                key={m.value}
                type="button"
                onClick={() => onSelect?.(m.value)}
                aria-pressed={value === m.value}
                className={`h-10 flex-1 rounded-full px-4 text-[13px] font-semibold transition-all ${
                  value === m.value
                    ? "bg-primary text-primary-foreground shadow-[0_4px_14px_rgba(106,90,224,0.35)]"
                    : "glass hover:-translate-y-px"
                }`}
              >
                <span className="mr-1.5 opacity-80">{m.face}</span>
                {m.label}
              </button>
            ))}
          </div>
        )}
      </CardContent>
    </Card>
  )
}

/* The streak grid: the last two weeks as soft dots. Done days fill mint,
   today gets the violet ring, missed days stay quiet glass. */
