        <Card className="py-10">
          <CardContent className="px-8 text-center">
            <h3 className="font-display text-[16px] font-bold">Programs didn&rsquo;t load</h3>
            <p className="mt-2 text-[13px] leading-relaxed text-muted-foreground">
